// core/pool-code.ts — the stock CLMM v5 pool wasm, embedded.
// Serialization law: bytes never cross the JSON/Qwik boundary — consumers
// send codeB64 (or use the global registry reference when registered).
// Source: pool7.clmm5-51fe5a.testnet deployed code (sha256 4750de4d6ddff260…,
// 158,940 bytes). Global registry check: hash 5oPU5mvJ… is NOT registered —
// new pools inline-deploy this code (~1.6 N storage on the pool account).

const POOL_WASM_B64 = "";

let bytesCache: Uint8Array | null = null;

export function poolWasmBytes(): Uint8Array {
  if (!bytesCache) {
    const bin = atob(POOL_WASM_B64);
    bytesCache = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytesCache[i] = bin.charCodeAt(i);
  }
  return bytesCache;
}
